-- Schema for the Studio clone (SQLite, local, single user).
-- Ids are UUIDs generated by the app (crypto.randomUUID / uuid4).
-- Times are ISO 8601 strings in UTC; audio positions are integer milliseconds.
-- Every connection must run: PRAGMA foreign_keys = ON; PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000;
-- Single user on localhost: no users table and no owner columns. If the app is ever exposed
-- beyond localhost, add users + user_id on projects and music_tracks, and an auth check per query.

create table projects (
  id               text primary key,
  title            text not null default 'Untitled project' check (length(title) between 1 and 200),
  -- The edit document: ordered blocks (speech | music | placeholder) referencing word ids
  -- and asset time ranges. The edit decision list is derived from it.
  doc_json         text not null default '{"blocks":[]}' check (json_valid(doc_json)),
  doc_version      integer not null default 0,  -- optimistic concurrency between tabs
  duration_ms      integer not null default 0 check (duration_ms >= 0),
  enhance_enabled  integer not null default 0 check (enhance_enabled in (0, 1)),
  enhance_strength integer not null default 70 check (enhance_strength between 0 and 100),
  created_at       text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at       text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
create index projects_updated_at_idx on projects (updated_at desc);

create table media_assets (
  id            text primary key,
  project_id    text not null references projects(id) on delete cascade,
  kind          text not null check (kind in ('audio', 'video')),
  source        text not null check (source in ('recording', 'upload')),
  original_name text,
  original_path text not null,           -- relative to data/media
  master_path   text,                    -- 48 kHz WAV made by the transcode job
  proxy_dir     text,                    -- 24 kHz mono Opus chunks of 30 s, for playback
  enhanced_path text,                    -- output of the enhance job, for the current strength
  enhanced_strength integer check (enhanced_strength between 0 and 100),
  duration_ms   integer check (duration_ms >= 0),
  sample_rate   integer,
  channels      integer,
  size_bytes    integer check (size_bytes >= 0),
  status        text not null default 'uploading'
    check (status in ('uploading', 'recording', 'processing', 'ready', 'error')),
  error         text,
  created_at    text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at    text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
create index media_assets_project_idx on media_assets (project_id, created_at);

-- Chunks of an in-progress browser recording, so nothing is lost if the tab or network dies.
create table recording_chunks (
  asset_id    text not null references media_assets(id) on delete cascade,
  seq         integer not null check (seq >= 0),
  size_bytes  integer not null check (size_bytes >= 0),
  created_at  text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  primary key (asset_id, seq)            -- a retried chunk upload is idempotent
);

create table speakers (
  id          text primary key,
  project_id  text not null references projects(id) on delete cascade,
  label       text not null check (length(label) between 1 and 80),
  created_at  text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
create index speakers_project_idx on speakers (project_id);

create table transcripts (
  id               text primary key,
  asset_id         text not null unique references media_assets(id) on delete cascade,
  language         text not null check (language in ('en', 'es', 'fr', 'de', 'it', 'pt')),
  detect_speakers  integer not null default 0 check (detect_speakers in (0, 1)),
  model            text not null,         -- e.g. faster-whisper small
  status           text not null default 'pending'
    check (status in ('pending', 'processing', 'done', 'error')),
  error            text,
  created_at       text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at       text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Raw ASR output. Immutable once written: edits live in projects.doc_json,
-- corrections are stored there as a text override per word id.
create table words (
  id             text primary key,
  transcript_id  text not null references transcripts(id) on delete cascade,
  idx            integer not null check (idx >= 0),
  text           text not null,
  start_ms       integer not null check (start_ms >= 0),
  end_ms         integer not null,
  confidence     real check (confidence between 0 and 1),
  speaker_id     text references speakers(id) on delete set null,
  created_at     text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  constraint word_has_length check (end_ms > start_ms),
  unique (transcript_id, idx)
);
create index words_speaker_idx on words (speaker_id);

-- The user's own music library (own uploads or CC0). Shared across projects.
create table music_tracks (
  id           text primary key,
  title        text not null check (length(title) between 1 and 200),
  category     text not null check (category in ('intro', 'outro', 'transition', 'background')),
  path         text not null,
  duration_ms  integer not null check (duration_ms > 0),
  license      text not null,             -- 'own', 'CC0', or the licence name and URL
  created_at   text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at   text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
create index music_tracks_category_idx on music_tracks (category, title);

-- Work queue shared by the Next.js app (producer) and the Python worker (consumer).
create table jobs (
  id          text primary key,
  project_id  text not null references projects(id) on delete cascade,
  asset_id    text references media_assets(id) on delete cascade,
  type        text not null
    check (type in ('transcode', 'transcribe', 'diarize', 'enhance', 'render')),
  status      text not null default 'queued'
    check (status in ('queued', 'running', 'done', 'error', 'cancelled')),
  payload     text not null default '{}' check (json_valid(payload)),
  progress    real not null default 0 check (progress between 0 and 1),
  attempts    integer not null default 0 check (attempts >= 0),
  error       text,
  locked_at   text,                      -- set when a worker claims it; stale locks are retried
  created_at  text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
create index jobs_queue_idx on jobs (status, created_at);
create index jobs_project_idx on jobs (project_id, created_at);
create index jobs_asset_idx on jobs (asset_id);
-- Only one active job of each type per asset (no duplicate transcriptions on double click).
create unique index jobs_one_active_per_asset
  on jobs (asset_id, type) where status in ('queued', 'running') and asset_id is not null;

create table exports (
  id              text primary key,
  project_id      text not null references projects(id) on delete cascade,
  job_id          text references jobs(id) on delete set null,
  kind            text not null check (kind in
    ('audio_mp3', 'audio_wav', 'video_mp4', 'transcript_txt', 'transcript_pdf',
     'transcript_docx', 'clip', 'speaker_tracks')),
  range_start_ms  integer check (range_start_ms >= 0),
  range_end_ms    integer,
  doc_version     integer not null,      -- the edit that was rendered
  status          text not null default 'queued'
    check (status in ('queued', 'rendering', 'ready', 'error')),
  output_path     text,
  error           text,
  created_at      text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at      text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  constraint export_range check (range_end_ms is null or range_end_ms > range_start_ms)
);
create index exports_project_idx on exports (project_id, created_at desc);
create index exports_job_idx on exports (job_id);
